      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "report objective in thousands of vehicles per hour (raw capacity units)"
    },
    {
      "decision": "arc_set_inclusion",
      "evidence": "a capacity of \"0\" symbolizes that there is no direct superhighway linking those two cities",
